using GlobalErrorHandlingDemo.ExceptionHandlers;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOpenApi();

// Register Problem Details services and custom exception handler
builder.Services.AddProblemDetails();
builder.Services.AddExceptionHandler<GlobalExceptionHandler>();

var app = builder.Build();

if (app.Environment.IsDevelopment())
{
    app.MapOpenApi();
}

// Middleware that catches exceptions and converts them to Problem Details responses
app.UseExceptionHandler();

// Demo endpoints that throw various exceptions to verify global handling
var summaries = new[]
{
    "Freezing", "Bracing", "Chilly", "Cool", "Mild", "Warm", "Balmy", "Hot", "Sweltering", "Scorching"
};

app.MapGet("/weatherforecast", () =>
{
    var forecast = Enumerable.Range(1, 5).Select(index =>
        new WeatherForecast(
            DateOnly.FromDateTime(DateTime.Now.AddDays(index)),
            Random.Shared.Next(-20, 55),
            summaries[Random.Shared.Next(summaries.Length)]))
        .ToArray();
    return forecast;
})
.WithName("GetWeatherForecast");

app.MapGet("/demo/not-found", () =>
{
    throw new KeyNotFoundException("Item with the given ID was not found.");
});

app.MapGet("/demo/bad-request", () =>
{
    throw new ArgumentException("The 'email' parameter is not a valid email address.");
});

app.MapGet("/demo/conflict", () =>
{
    throw new InvalidOperationException("Cannot delete a user that has active orders.");
});

app.MapGet("/demo/server-error", () =>
{
    throw new Exception("Connection string contains a secret password!");
});

app.Run();

record WeatherForecast(DateOnly Date, int TemperatureC, string? Summary)
{
    public int TemperatureF => 32 + (int)(TemperatureC / 0.5556);
}

